CREATE TABLE access_meta(version INTEGER NOT NULL PRIMARY KEY);
INSERT INTO access_meta(version) VALUES(1);
CREATE TABLE access_identities(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,provider TEXT NOT NULL CHECK(provider IN('github','google')),subject TEXT NOT NULL,linked_at INTEGER NOT NULL,last_login_at INTEGER,UNIQUE(provider,subject),UNIQUE(user_id,provider));
CREATE TABLE access_credentials(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,name TEXT NOT NULL,prefix TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,scopes TEXT NOT NULL,audiences TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_used_at INTEGER,revoked_at INTEGER);
CREATE INDEX access_credentials_user ON access_credentials(user_id,id);
CREATE TABLE access_clients(client_id TEXT PRIMARY KEY,client_name TEXT NOT NULL,redirect_uris TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE access_consents(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,session_binding TEXT NOT NULL,browser_hash TEXT NOT NULL,client_id TEXT NOT NULL REFERENCES access_clients(client_id),redirect_uri TEXT NOT NULL,state TEXT NOT NULL,scopes TEXT NOT NULL,resource TEXT NOT NULL,challenge TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE INDEX access_consents_expiry ON access_consents(expires_at);
CREATE TABLE access_codes(code_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,client_id TEXT NOT NULL REFERENCES access_clients(client_id),redirect_uri TEXT NOT NULL,scopes TEXT NOT NULL,resource TEXT NOT NULL,challenge TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE access_grants(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,client_id TEXT NOT NULL REFERENCES access_clients(client_id),scopes TEXT NOT NULL,resource TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_used_at INTEGER,revoked_at INTEGER);
CREATE INDEX access_grants_user ON access_grants(user_id,id);
CREATE TABLE access_tokens(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,grant_id TEXT NOT NULL REFERENCES access_grants(id),kind TEXT NOT NULL CHECK(kind IN('access','refresh')),scopes TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER,revoked_at INTEGER);
CREATE INDEX access_tokens_grant ON access_tokens(grant_id);
CREATE TABLE access_provider_flows(state_hash TEXT PRIMARY KEY,provider TEXT NOT NULL,purpose TEXT NOT NULL,user_id INTEGER,session_binding TEXT,browser_hash TEXT NOT NULL,verifier TEXT NOT NULL,nonce TEXT NOT NULL,next_path TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE INDEX access_provider_flows_expiry ON access_provider_flows(expires_at);
CREATE TABLE access_events(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id TEXT NOT NULL UNIQUE,at INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN('operation','security')),transport TEXT NOT NULL,operation TEXT NOT NULL,user_id INTEGER,client_id TEXT,credential_id TEXT,grant_id TEXT,status INTEGER NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('pending','success','failure','interrupted')),duration_ms INTEGER NOT NULL DEFAULT 0);
CREATE INDEX access_events_user_time ON access_events(user_id,at,id);
CREATE INDEX access_events_pending ON access_events(outcome,at);
CREATE TABLE access_daily(day TEXT NOT NULL,user_id INTEGER NOT NULL,transport TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,successes INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,pending INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,user_id,transport));
